// Checks the built site in dist/ (or --dir <path>). Run after `npm run build`.
//
//   npm run verify                 errors fail, translation gaps warn (used by deploy: a TalloRes
//                                  data push must never be blocked by a missing translation)
//   npm run verify -- --strict     translation gaps fail too (used on pull requests)
//
// No HTML parser dependency: the output is generated by our own templates, so targeted regexes suffice.
import { existsSync, readFileSync, statSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { pageUrl } from '../src/lib/seo';
import { loadSite } from '../src/lib/site-data';

const args = process.argv.slice(2);
const strict = args.includes('--strict');
const dist = resolve(args.includes('--dir') ? args[args.indexOf('--dir') + 1] : 'dist');
const { restaurant: r, content: c, issues } = loadSite();

const errors: string[] = [];
const warnings: string[] = [];
const fail = (m: string) => errors.push(m);

const read = (rel: string) => {
  const f = join(dist, rel);
  if (!existsSync(f)) { fail(`missing ${rel}`); return ''; }
  return readFileSync(f, 'utf8');
};

/** Local href/src/srcset targets must exist in dist. */
function checkLinks(rel: string, html: string) {
  const base = dirname(join(dist, rel));
  const urls = [
    ...[...html.matchAll(/\s(?:href|src)="([^"]+)"/g)].map((m) => m[1]),
    ...[...html.matchAll(/\ssrcset="([^"]+)"/g)].flatMap((m) => m[1].split(',').map((s) => s.trim().split(/\s+/)[0])),
  ];
  for (const raw of urls) {
    const u = raw.replace(/&amp;/g, '&');
    if (/^(https?:|mailto:|tel:|data:|#|\/\/)/.test(u)) continue;
    const path = decodeURIComponent(u.split(/[?#]/)[0]);
    let target = path.startsWith('/') ? join(dist, path) : join(base, path);
    if (existsSync(target) && statSync(target).isDirectory()) target = join(target, 'index.html');
    if (!existsSync(target)) fail(`${rel}: broken link ${u}`);
  }
}

function checkPage(rel: string, lang: string, opts: { canonical: string; home: boolean }) {
  const html = read(rel);
  if (!html) return;
  if (!/^<!DOCTYPE html>/i.test(html)) fail(`${rel}: no doctype`);
  if (!html.includes(`<html lang="${lang}"`)) fail(`${rel}: <html lang> is not "${lang}"`);
  const h1 = (html.match(/<h1[\s>]/g) ?? []).length;
  if (h1 !== 1) fail(`${rel}: ${h1} <h1> elements, expected exactly 1`);
  if (!html.includes(`<link rel="canonical" href="${opts.canonical}"`)) fail(`${rel}: canonical is not ${opts.canonical}`);
  if (!/<title>[^<]+<\/title>/.test(html)) fail(`${rel}: empty <title>`);
  if (!/<meta name="description" content="[^"]+"/.test(html)) fail(`${rel}: empty meta description`);
  const text = html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/g, '');
  for (const bad of ['undefined', 'NaN', '[object Object]']) if (text.includes(bad)) fail(`${rel}: contains "${bad}"`);
  if (c.languages.length > 1) {
    for (const l of c.languages) if (!html.includes(`hreflang="${l}"`)) fail(`${rel}: no hreflang for ${l}`);
    if (opts.home && !html.includes('hreflang="x-default"')) fail(`${rel}: no hreflang x-default`);
  }
  if (opts.home) {
    const ld = html.match(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/);
    if (!ld) fail(`${rel}: no JSON-LD`);
    else {
      try {
        const data = JSON.parse(ld[1]);
        if (data['@type'] !== 'Restaurant') fail(`${rel}: JSON-LD @type is ${data['@type']}`);
        for (const k of ['name', 'address', 'telephone', 'openingHoursSpecification', 'potentialAction']) if (!data[k]) fail(`${rel}: JSON-LD has no ${k}`);
      } catch (e) { fail(`${rel}: JSON-LD does not parse (${(e as Error).message})`); }
    }
    if (!html.includes('data-widget')) fail(`${rel}: no reservation widget`);
    if (/<iframe[^>]+openstreetmap/.test(html)) fail(`${rel}: map iframe loads without a click`);
  }
  checkLinks(rel, html);
}

for (const lang of c.languages) {
  checkPage(`${lang}/index.html`, lang, { canonical: pageUrl(r, lang), home: true });
  checkPage(`${lang}/privacy/index.html`, lang, { canonical: `${pageUrl(r, lang)}privacy/`, home: false });
}

const sitemap = read('sitemap.xml');
for (const lang of c.languages) if (sitemap && !sitemap.includes(`<loc>${pageUrl(r, lang)}</loc>`)) fail(`sitemap.xml: no <loc> for ${lang}`);
const robots = read('robots.txt');
if (robots && !robots.includes(`Sitemap: ${r.siteUrl}/sitemap.xml`)) fail('robots.txt: no Sitemap line');
if (robots && /Disallow:\s*\/\s*$/m.test(robots)) fail('robots.txt: disallows the whole site');
const llms = read('llms.txt');
if (llms && !llms.startsWith(`# ${r.name}`)) fail('llms.txt: does not start with the restaurant name');
const redirects = read('_redirects');
if (redirects && !redirects.includes(`/${c.languages[0]}/`)) fail('_redirects: / does not redirect to the main language');

for (const i of issues) {
  const m = `translation ${i.kind}: ${i.lang} ${i.path} (run npm run translations:status)`;
  (strict ? errors : warnings).push(m);
}

for (const w of warnings) console.warn(`warn  ${w}`);
for (const e of errors) console.error(`error ${e}`);
console.log(`\nverify: ${c.languages.length} languages, ${errors.length} errors, ${warnings.length} warnings${strict ? ' (strict)' : ''}`);
process.exit(errors.length ? 1 : 0);
